#!/usr/bin/env python3
"""Check of the design's A-TWIST derivation (repair-design WO-I-5) on SYNTHETIC
cells only (field degree n in {9, 10, 15}; forbidden set refused). Written by
the red team from WO-I-5's text; brute force enumerates K = F_2[z]/(P).

A-TWIST as WO-I-5 states it: M_0 = Y; M_(j+1) = lambda^(sigma^(j n' + r))(M_j)
for j = 0..q-1; H_tw = Y^(2^s) + lambda(M_q); R = Y^(2^n) mod H_tw (n squarings:
sigma on coefficients, then reduce); G = monic gcd(H_tw, R - Y); roots of G in
K (here by evaluation over K, adequate at these sizes); closing test
x = M_q(y), x^(2^r) == y, x^(2^n') == lambda(x). Compared with brute force.
Also: A-TWIST on F_2 lambda versus the plain derivation-(A) H."""
import random, json, sys
from rt_synth import guard

def kmul(a, b, P, n):
    r = 0
    while b:
        if b & 1: r ^= a
        b >>= 1; a <<= 1
        if a >> n & 1: a ^= P
    return r
def kpow2(a, k, P, n):
    for _ in range(k): a = kmul(a, a, P, n)
    return a
def kinv(a, P, n):  # a^(2^n - 2)
    r, e, b = 1, (1 << n) - 2, a
    while e:
        if e & 1: r = kmul(r, b, P, n)
        b = kmul(b, b, P, n); e >>= 1
    return r
def irreducible(P, n):
    # z^(2^n) == z mod P and gcd(z^(2^(n/p)) - z, P) == 1 for primes p | n (F_2[z] ints)
    def pm(a, m):
        dm = m.bit_length() - 1
        while a and a.bit_length() - 1 >= dm: a ^= m << (a.bit_length() - 1 - dm)
        return a
    def g(a, b):
        while b: a, b = b, pm(a, b)
        return a
    def x2k(k):
        r = 2
        for _ in range(k): r = pm(int('0'.join(bin(r)[2:]), 2), P)
        return r
    if x2k(n) != 2: return False
    ps = [p for p in range(2, n + 1) if n % p == 0 and all(p % t for t in range(2, p))]
    return all(g(P, x2k(n // p) ^ 2) == 1 for p in ps)

# K[Y] polynomials: list of K elements, index = degree, no trailing zeros
def trim(f):
    while f and f[-1] == 0: f.pop()
    return f
def padd(f, g):
    r = [0] * max(len(f), len(g))
    for i, c in enumerate(f): r[i] ^= c
    for i, c in enumerate(g): r[i] ^= c
    return trim(r)
def pmul(f, g, P, n):
    if not f or not g: return []
    r = [0] * (len(f) + len(g) - 1)
    for i, a in enumerate(f):
        if a:
            for j, b in enumerate(g):
                if b: r[i + j] ^= kmul(a, b, P, n)
    return trim(r)
def pmod(f, g, P, n):
    f = list(f); dg = len(g) - 1; inv = kinv(g[-1], P, n)
    while len(f) - 1 >= dg and f:
        c = kmul(f[-1], inv, P, n); sh = len(f) - 1 - dg
        for j, b in enumerate(g):
            if b: f[sh + j] ^= kmul(c, b, P, n)
        trim(f)
    return f
def pgcd(f, g, P, n):
    while g: f, g = g, pmod(f, g, P, n)
    if f:
        inv = kinv(f[-1], P, n); f = [kmul(c, inv, P, n) for c in f]
    return f
def sigma_coeffs(f, j, P, n): return [kpow2(c, j % n, P, n) for c in f]
def compose(f, g, P, n):   # f(g(Y)), Horner
    r = []
    for c in reversed(f):
        r = pmul(r, g, P, n); r = padd(r, [c])
    return r
def peval(f, x, P, n):
    r = 0
    for c in reversed(f): r = kmul(r, x, P, n) ^ c
    return r

def a_twist(lam, n, n1, P):
    q, r = divmod(n, n1); s = n1 - r
    M = [0, 1]
    for j in range(q):
        M = compose(sigma_coeffs(lam, j * n1 + r, P, n), M, P, n)
    H = padd([0] * (1 << s) + [1], compose(lam, M, P, n))
    if not H: return None
    R = pmod([0, 1], H, P, n)
    for _ in range(n):
        sq = [0] * (2 * len(R) - 1 if R else 0)
        for i, c in enumerate(R): sq[2 * i] = kmul(c, c, P, n)
        R = pmod(trim(sq), H, P, n)
    G = pgcd(H, padd(R, [0, 1]), P, n)
    yroots = [y for y in range(1 << n) if peval(G, y, P, n) == 0]
    assert len(yroots) == len(G) - 1, 'G does not split into distinct roots over K'
    acc = []
    for y in yroots:
        x = peval(M, y, P, n)
        if kpow2(x, r, P, n) == y and kpow2(x, n1, P, n) == peval(lam, x, P, n):
            acc.append(x)
    return {'N': len(acc), 'roots': sorted(acc), 'deg_H': len(H) - 1, 'h_roots_in_K': len(yroots)}

def brute(lam, n, n1, P):
    return sorted(x for x in range(1 << n) if kpow2(x, n1, P, n) == peval(lam, x, P, n))

if __name__ == '__main__':
    rng = random.Random(20261002)
    out = []
    for n, n1, P in [(9, 4, (1 << 9) | (1 << 4) | 1), (10, 3, (1 << 10) | (1 << 3) | 1), (15, 4, (1 << 15) | 2 | 1)]:
        guard(n)
        assert irreducible(P, n), (n, P)
        res = {'n': n, 'n1': n1, 'modulus': bin(P), 'K_coeff_cases': 0, 'agree': 0, 'disagree': [],
               'F2_cases': 0, 'F2_agree_with_bruteforce': 0, 'h_vanishes': 0}
        for d in (2, 3, 4):
            for _ in range(8 if n == 15 else 12):
                lam = [rng.getrandbits(n) for _ in range(d)] + [rng.randrange(1, 1 << n)]
                t = a_twist(lam, n, n1, P)
                if t is None: res['h_vanishes'] += 1; continue
                b = brute(lam, n, n1, P)
                res['K_coeff_cases'] += 1
                if t['roots'] == b: res['agree'] += 1
                else: res['disagree'].append([d, t['N'], len(b)])
            for _ in range(3):
                lam = [rng.getrandbits(1) for _ in range(d)] + [1]
                t = a_twist(lam, n, n1, P); b = brute(lam, n, n1, P)
                res['F2_cases'] += 1
                if t is not None and t['roots'] == b: res['F2_agree_with_bruteforce'] += 1
        print(json.dumps(res)); sys.stdout.flush()

