#!/usr/bin/env python3
"""PTM-D3 against the design's independence acceptance check AC-7, on SYNTHETIC
cells only (n = 17 and 19; forbidden set refused). The design is a design (no
r1 code exists), so AC-7 is modelled from its text:
  WO-I-10: every polynomial operation goes through gf2x public functions, each
           recording (function, modulus degree, modulus digest) in a trace.
  AC-7:    static rule (imports; bitwise operators only in gf2x/fieldk) and the
           trace rule "no route squares a residue modulo the cell's L or rad(L)
           (a chain of two or more such squarings fails), and S-BERL computes no
           gcd with X^(2^n) - X".
Routes fed through it (all written with gf2x public functions only, so the
static rule passes them all):
  S-BERL   legitimate Berlekamp count (Q rows by shift-by-two then reduce).
  D3a      I_direct by a squaring primitive sqrmod(r, L) chain (the literal PTM-D3).
  D3b      I_direct by mul(r, r) then mod(., L): repeated squaring under the
           function names of a generic product and a reduction.
  D3c      I_direct by the Frobenius matrix: v <- Q v, n times, using the very Q
           S-BERL builds (adds only), then gcd(L, v + X).
Audits: LITERAL (the stated schema and rule) and HARDENED (operand digests;
equal-operand products reduced mod L or rad L; any operand equal to
X^(2^k) mod L for k > n'; any gcd of L or rad L with v = X^(2^k) + X mod L,
k > n'; residues computed by the auditor on the synthetic cell).
"""
import hashlib, json, random
from rt_synth import guard, pgcd as _gcd, pmod as _mod, pmul as _mul, psq as _sq, \
    pdivmod as _divmod, deriv as _deriv, x2k_mod, deg

TRACE = []
OPERAND_DIGESTS = True   # the hardened audit reads them; the literal audit ignores them
def dg(x): return hashlib.sha256(str(x).encode()).hexdigest()[:16]
def rec(fn, modulus, *ops):
    TRACE.append({'fn': fn, 'mod_deg': None if modulus is None else deg(modulus),
                  'mod_digest': None if modulus is None else dg(modulus),
                  'ops': [dg(o) for o in ops] if OPERAND_DIGESTS else None,
                  'equal_operands': (len(ops) == 2 and ops[0] == ops[1])})
# ---- mock gf2x public functions (the only place bit operations live) ----
def add(a, b): rec('add', None, a, b); return a ^ b
def mul(a, b): rec('mul', None, a, b); return _mul(a, b)
def shift(a, k): rec('shift', None, a); return a << k
def mod(a, m): rec('mod', m, a); return _mod(a, m)
def mulmod(a, b, m): rec('mulmod', m, a, b); return _mod(_mul(a, b), m)
def sqrmod(a, m): rec('sqrmod', m, a); return _mod(_sq(a), m)
def gcd(a, b): rec('gcd', a if deg(a) >= deg(b) else b, a, b); return _gcd(a, b)
def divexact(a, b): rec('div', b, a); q, r = _divmod(a, b); assert r == 0; return q
def derivative(a): rec('deriv', None, a); return _deriv(a)
def bit(a, i): rec('bit', None, a); return (a >> i) & 1
def degree(a): return deg(a)

# ---- routes ----
def rad(f):
    if degree(f) <= 0: return 1
    dv = derivative(f)
    if dv == 0:
        s = bin(f)[2:][::-1]; return rad(int(s[0::2][::-1], 2))
    c = gcd(f, dv); w = divexact(f, c); rc = rad(c); g = gcd(w, rc)
    return divexact(mul(w, rc), g)
def build_Q(R):
    m = degree(R); rows = [1]
    for i in range(1, m): rows.append(mod(shift(rows[-1], 2), R))
    return rows
def s_berl(L, n):
    R = rad(L); m = degree(R); Q = build_Q(R)
    M = [add(Q[i], 1 << i) for i in range(m)]           # rows of Q - I
    # kernel of v -> v (Q - I): Gaussian elimination on columns via adds
    rows = [(M[i], 1 << i) for i in range(m)]
    basis = []; piv = {}
    for vec, comb in rows:
        for p in sorted(piv, reverse=True):
            if bit(vec, p): vec = add(vec, piv[p][0]); comb = add(comb, piv[p][1])
        if vec == 0: basis.append(comb)
        else: piv[degree(vec)] = (vec, comb)
    k = len(basis); factors = [R]
    for v in basis:
        if len(factors) == k: break
        nxt = []
        for g in factors:
            if degree(g) > 1:
                h = gcd(g, mod(v, g))
                if 0 < degree(h) < degree(g): nxt += [h, divexact(g, h)]; continue
            nxt.append(g)
        factors = nxt
    assert len(factors) == k
    return sum(degree(f) for f in factors if n % degree(f) == 0)
def d3a(L, n):
    r = mod(2, L)
    for _ in range(n): r = sqrmod(r, L)
    return degree(gcd(L, add(r, 2)))
def d3b(L, n):
    r = mod(2, L)
    for _ in range(n): r = mod(mul(r, r), L)
    return degree(gcd(L, add(r, 2)))
def d3c(L, n):
    R = rad(L); Q = build_Q(R); v = 2
    for _ in range(n):
        w = 0
        for i in range(degree(R)):
            if bit(v, i): w = add(w, Q[i])
        v = w
    return degree(gcd(R, add(v, 2)))

def literal_audit(trace, Ldig, Rdig):
    chain = 0
    for e in trace:
        if e['fn'] == 'sqrmod' and e['mod_digest'] in (Ldig, Rdig):
            chain += 1
            if chain >= 2: return 'FAIL (squaring chain modulo L or rad(L))'
        elif e['fn'] not in ('sqrmod',):
            pass
    return 'PASS'
def hardened_audit(trace, L, R, n, n1):
    bad = {dg(x2k_mod(k, L)) for k in range(n1 + 1, n + 1)} | {dg(x2k_mod(k, R)) for k in range(n1 + 1, n + 1)}
    badg = {dg(x2k_mod(k, L) ^ 2) for k in range(n1 + 1, n + 1)} | {dg(x2k_mod(k, R) ^ 2) for k in range(n1 + 1, n + 1)}
    LR = (dg(L), dg(R)); prev = None
    for e in trace:
        if e['equal_operands'] and e['fn'] in ('mul', 'mulmod'):
            prev = 'equal_mul'
            if e['fn'] == 'mulmod' and e['mod_digest'] in LR: return 'FAIL (equal-operand product modulo L or rad L)'
            continue
        if prev == 'equal_mul' and e['fn'] == 'mod' and e['mod_digest'] in LR:
            return 'FAIL (equal-operand product then reduction modulo L or rad L)'
        prev = None
        if e['fn'] == 'sqrmod' and e['mod_digest'] in LR: return 'FAIL (squaring modulo L or rad L)'
        if any(o in bad for o in e['ops']): return 'FAIL (operand equals X^(2^k) mod L, k > n1)'
        if e['fn'] == 'gcd' and any(o in badg for o in e['ops']): return 'FAIL (gcd with X^(2^k)+X mod L, k > n1)'
    return 'PASS'
def literal_rule_x2k_any_k(trace, L, R, n):
    """The WO-I-6 / A1 text read literally: 'never forms X^(2^k) mod L or rad(L) for k >= 2 by any means'."""
    ks = set()
    for k in range(2, n + 1):
        for tgt in (x2k_mod(k, L), x2k_mod(k, R)):
            if any(dg(tgt) in e['ops'] for e in trace): ks.add(k)
    return sorted(ks)

if __name__ == '__main__':
    out = []
    rng = random.Random(3)
    for n, n1 in [(17, 5), (19, 5), (17, 4)]:
        guard(n)
        lams = [l for l in range(1 << 3, 1 << 8) if l not in (0b10000, 0b10100, 0b10010, 0b10110)]
        lams = rng.sample(lams, 6)
        for lam in lams:
            L = (1 << (1 << n1)) ^ lam
            ref = deg(_gcd(L, x2k_mod(n, L) ^ 2))     # I_direct shape, auditor-side
            R = _gcd(L, L)  # placeholder, replaced below
            row = {'n': n, 'n1': n1, 'lambda': bin(lam), 'N_ref': ref}
            for name, fn in [('S-BERL', s_berl), ('D3a', d3a), ('D3b', d3b), ('D3c', d3c)]:
                TRACE.clear()
                N = fn(L, n)
                tr = list(TRACE)
                TRACE.clear(); Rr = rad(L); TRACE.clear()
                row[name] = {'N': N, 'equals_I_direct': N == ref,
                             'event_kinds': sorted({e['fn'] for e in tr}),
                             'literal_AC7': literal_audit(tr, dg(L), dg(Rr)),
                             'hardened': hardened_audit(tr, L, Rr, n, n1),
                             'literal_text_rule_k_formed': literal_rule_x2k_any_k(tr, L, Rr, n)}
            kinds_sb = set(row['S-BERL']['event_kinds'])
            for name in ('D3a', 'D3b', 'D3c'):
                row[name]['kinds_subset_of_S_BERL'] = set(row[name]['event_kinds']) <= kinds_sb
            out.append(row)
            print(json.dumps(row))

